"""补充扩写：把简介偏短的 37 条扩到 150–200 字，补充赛制细节、评审关注点与历史背景。"""

INTRO_EXTRA = {
    "sdnu-047": "山东省心理学领域的应用技能赛事，通常由省心理学会与省内高校联合承办，赛道含心理咨询技能、心理测量应用与心理健康教育方案设计。比赛形式以「案例实操 + 现场模拟」为主：给出一个真实咨询案例或心理测评情境，要求选手在规定时间内完成评估、干预方案设计与现场演示，评委由注册督导师与一线心理健康教师组成。它检验的不是论文写得多好，而是你能不能坐下来把一个真实的人接住。",
    "sdnu-064": "聚焦英语词汇能力的专项赛事，采用线上机考形式，题型含词义辨析、语境填空、同义替换与学术词汇应用。赛程短、门槛低，从报名到出成绩通常不超过一个月。它的价值主要在「以赛促学」：给自己一个明确的截止日期，把词汇量从四六级水平推到考研或雅思水平，顺便拿一个国家级奖项记录。",
    "sdnu-067": "以东方美学为主题的艺术设计作品征集活动，由设计类媒体与院校联合发起，征集方向含视觉设计、插画、产品与空间表达。评审关注两点：文化元素是否被真正理解而非符号堆砌，当代设计语言能否与之自然衔接。活动性质介于赛事与展览征集之间，入选作品通常会进入线上展厅或线下巡展。",
    "sdnu-035": "聚焦等离子体科学与应用的专项赛事，赛题涉及低温等离子体产生、诊断与工业应用（材料改性、环境治理、生物医学），形式以科技作品与学术报告为主，通常与中国物理学会等离子体专业委员会的年会同期举办。参赛规模不大，评审多为该领域的教授与研究员，交流属性强于竞争属性。",
    "sdnu-060": "面向高校设计学生的创意设计赛事，赛道含视觉传达、产品设计、空间设计与数字创意，评审强调东方美学元素与现代设计语言的结合。赛事分初评与终评两轮：初评看作品集与创意说明，终评需要提交可演示的成品或高保真效果图。规模中等、参赛门槛适中，适合作为设计类课程的成果出口。",
    "sdnu-069": "面向中国高校俄语学习者的演讲赛事，由中俄相关机构合作举办，赛制含命题演讲、即兴演讲与评委问答三个环节，评审含俄语母语专家。命题多围绕中俄文化交流与当代青年议题，考察的不只是语音语调，还有观点组织与临场应变。是俄语专业学生少有的高水平实战平台。",
    "sdnu-059": "依托马栏山视频文创产业园的青年影像创作活动，由园区与省内高校联合举办，赛道含短视频、纪录片、动画与创意策划。评审团由平台方、制作公司与高校教师组成，评分兼顾内容创意、拍摄剪辑完成度与传播潜力。优秀作品有机会获得园区企业的流量扶持与项目合作，是影视与新媒体方向少见的产业对接机会。",
    "sdnu-044": "山东省面向大学生发明创造的省级赛事，赛道含机械电子、信息通信、材料化工、生物医药与生活创意。评审看重两点：技术方案是否解决了真实痛点，以及是否具备专利申报条件。优秀作品会被推荐参加全国发明展览会，部分项目能对接企业完成转化。",
    "sdnu-049": "山东省大学生科技节下设的环保主题创意赛事，作品形式含环保科技作品、公益设计、宣传方案与调研报告。评审关注创意的可实现性与环保效益的可量化程度——「减少了多少排放、节省了多少资源」比口号更有说服力。是省内环保主题最对口的赛事，环境类专业几乎每年都有队伍参加。",
    "sdnu-058": "面向亚太地区青年设计师的当代设计赛事，赛道含视觉传达、产品、空间与数字媒体。评审强调观念性与实验性，鼓励突破商业设计惯性的作品，参赛作品整体风格偏艺术化。对希望走艺术设计深造路线的同学，它是一个能接触国际评审视角的窗口。",
    "sdnu-061": "由中国建筑装饰协会主办的环境设计专项赛事，赛道含室内设计、景观设计与公共空间设计。评审团以一线设计机构主创与装饰企业设计师为主，评分标准贴近实际项目落地要求：平面功能是否合理、材料与工艺是否可实施、造价是否可控。对想进设计院或装饰企业的同学，这类行业赛事比学科竞赛更对口。",
    "sdnu-011": "面向高校设计专业学生的全国性赛事，赛道含视觉传达、产品设计、环境艺术与数字媒体，评审侧重创意表达与完成度。赛事分初评与终评，终评需要提交完整的设计说明与效果呈现。参赛门槛适中，适合把课程作业系统化打磨之后参赛。",
    "sdnu-037": "面向高校学生的数字创新设计赛事，赛道含视觉设计、数字产品、交互体验与文化创意，强调用数字手段表达传统文化与在地文化。评审关注文化转译的准确度与设计语言的当代性，反感简单的纹样拼贴。赛事规模中等，适合作为文化创意方向的项目实践记录。",
    "sdnu-062": "面向人力资源管理及相关专业的实践赛事，赛道含人力资源案例分析与实务设计。比赛通常给出真实企业的人力情境（招聘、绩效、劳动关系），要求团队在规定时间内完成诊断与方案设计并现场答辩，评审含企业 HR 负责人，方案的可执行性是核心评分点。",
    "sdnu-004": "数学建模方向的全国性赛事，赛制与主流建模竞赛一致：三人一队、限定时间内针对开放性问题完成建模、求解与论文写作。赛题覆盖工程优化、经济预测与社会系统分析，评审按模型的合理性、结果的正确性与论文规范性综合打分。相比国赛，它的竞争压力较小，适合作为积累完整参赛经验的第一站。",
    "sdnu-012": "由教育部、国家语委主办的中华经典诵写讲大赛下设赛项，要求参赛者选取经典诗词进行讲解，提交 15 分钟左右的讲解视频与配套教案。评审关注三点：文本理解是否准确（有无硬伤）、讲解是否有感染力、教学设计是否完整（目标、重难点、活动设计）。对师范生来说，这份视频可以直接剪进教师招聘的试讲材料。",
    "sdnu-068": "面向高校学生的机器人与算法应用赛事，赛题结合机器人路径规划、视觉识别与算法优化，采用线上提交方案与现场答辩结合的形式。赛事规模相对较小，评审更看重方案的技术思路是否清晰，而不是硬件做得多复杂，适合作为进入机器人领域的第一次尝试。",
    "sdnu-003": "数学建模方向的国际赛事，赛制与国际数学建模挑战赛类似，要求在 4 天左右针对开放性问题完成建模、求解与英文论文写作。参赛队伍来自多个国家和地区，论文需符合国际学术写作规范（摘要、假设、模型、灵敏度分析、优缺点）。它的主要价值是训练英文论文写作与国际赛制适应能力。",
    "sdnu-046": "山东省大学生科技节下设的地理学科赛事，赛道含地理教学创新、地理科技创新与社会实践。教学创新赛道比的是地理课堂设计（含教具、实验、研学方案），科技创新赛道比的是 GIS 应用与野外调研成果。地理科学师范与非师范方向都能找到对口赛道，师范生尤其适合走教学创新赛道。",
    "sdnu-078": "依托在线实验平台举办的心理学实验赛事，参赛队需完成实验程序搭建（jsPsych 或 PsychoPy）、被试招募、数据采集与报告撰写，重点考察实验设计的严谨性与在线实验的可复现性。评审会追问「注意力检验怎么做的、剔除标准是什么、样本量怎么定的」——这三问答不上来，数据再漂亮也拿不到高分。",
    "sdnu-043": "山东省创新创业类赛事，含「浪曦杯」专项，强调「动手造物」：赛道含智能硬件、软件应用、文化创意与生活发明。评审看重作品的完整度与可演示性——能不能当场跑通、能不能让人一眼看懂解决了什么问题。省内高校参与面较广，是省级创新创业赛事的主要入口之一。",
    "sdnu-055": "面向师范生的高水平教学技能赛事，分学科进行，要求完成教学设计、模拟授课与答辩三个环节，评审团由一线特级教师与学科教研员组成。评分维度含教学目标、内容处理、教学方法、板书与语言、课堂应变。它是师范生教学能力的权威检验，部分地市教育局会直接关注获奖名单。",
    "sdnu-009": "面向全国高校学生的创新创业邀请赛，要求提交完整商业计划书并完成路演答辩，评审关注项目创新性、商业模式可行性与团队执行力。路演环节通常限时 8 分钟加 5 分钟问答，投资人评委最爱问「你的壁垒是什么、获客成本多少」。优秀项目有机会获得孵化资源与投资对接。",
    "sdnu-029": "由中国统计教育学会主办的统计类赛事，要求围绕经济社会问题完成数据采集、统计建模与报告撰写。评审看重方法的恰当性与结论的稳健性：用错模型（比如对时序数据直接跑 OLS）比结论平淡更致命。与数学建模国赛相比，它更强调统计推断与假设检验，而不是机理建模。",
    "sdnu-052": "面向数字技术人才的省级赛事，赛项覆盖数字孪生、工业软件、数据分析与智能制造，同时设国际数字工程师邀请赛道。赛事与山东省数字工程师人才评价体系衔接，获奖记录可作为省内数字产业人才认定的参考。适合关注工业数字化方向、希望留在山东就业的同学。",
    "sdnu-070": "面向全球青年艺术家的国际艺术赛事，媒介含绘画、版画、摄影、数字艺术与混合媒介，评审团由国际策展人与艺术家组成，获奖作品有机会参与国际巡展。它更看重个人创作语言的独特性而非技法熟练度，适合已经有成型创作系列的同学用它检验自己的作品能否被国际评审读懂。",
    "sdnu-006": "面向高校学生的暑期社会实践专项活动，要求深入乡村开展实地调研，以文字、影像或调研报告形式记录村庄的产业、人物与变迁。评审看重调研的实地深度与叙事质量：是真正住下来听故事，还是走一圈拍几张照片，评委一眼就能看出来。优秀作品会被集结出版或展出。",
    "sdnu-033": "面向电气工程与等离子体方向的专业赛事，内容涉及高电压绝缘、放电特性、等离子体材料处理与环保应用，参赛形式含科技作品与调研报告。赛事规模不大但专业性强，评审多为电气工程领域的教授与电网专家，是电气工程方向少有的对口竞赛。",
    "sdnu-076": "山东省大学生科技节下设的省级数学赛事，含数学竞赛（个人笔试，同时作为全国大学生数学竞赛山东赛区）与数学建模竞赛（团队三天一题）两部分。数学竞赛按专业分组的规则与国赛一致，建模部分赛题偏应用。省级奖项是国赛前的低成本练兵，周期短、投入小。",
    "sdnu-051": "山东省大学生科技节下设赛事，聚焦乡村人居环境改善与清洁能源应用，要求提出可落地的设计方案或技术方案。评审关注实地调研深度与方案的可行性：是否真的下过乡、方案造价是否在村镇可承受范围内、有没有考虑当地的气候与生活习惯。与乡村振兴战略直接对接，方案有真实的落地场景。",
    "sdnu-019": "由中国地理信息产业协会主办的专业赛事，考察 GIS 空间数据处理、空间分析建模、遥感解译与专题制图能力，赛题多取自国土、规划、环保等真实业务场景。比赛通常分软件操作与作品答辩两段：先在限时内完成给定的空间分析任务，再展示自选作品并回答评委关于数据来源与技术路线的追问。",
    "sdnu-048": "山东省物理学会组织的省级学科竞赛，以个人笔试为主，考察力学、电磁学、光学、热学与近代物理的综合运用，题目难度高于期末但低于全国大学生物理竞赛决赛。对物理基础扎实的同学，这是一条低成本拿省级奖的途径，也可以当作全国大学生物理竞赛的赛前摸底。",
    "sdnu-010": "金砖国家框架下的国际技能赛事，赛项覆盖人工智能应用、增材制造、工业机器人、数字孪生、网络安全等方向，中国赛区选拔后进入国际赛。赛事由金砖国家工商理事会技能发展工作组推动，与国际技能标准对接，赛题按岗位真实工作流程设计，实操权重远高于理论笔试。",
    "sdnu-040": "面向高校学生的算法编程赛事，题目以数据结构与经典算法为主，采用在线评测与限时排名，难度梯度从入门到进阶。相比 ICPC 与 CCPC，它的参赛门槛更低、赛程更短，通常一场比赛 2–3 小时、四五道题，适合作为算法训练的阶段性检验与刷题节奏的锚点。",
    "sdnu-023": "由中国数学会主办的学科竞赛，分数学专业组与非数学专业组，初赛为个人笔试，考察数学分析与高等代数（专业组）或高等数学（非专业组）的综合运用，决赛难度接近考研数学的拔高题。它按赛区独立评奖，山东赛区与省级数学竞赛共用一场考试，因此一次参赛可以拿到两份成绩。",
    "sdnu-039": "面向新文科建设的实践创新赛事，鼓励用数字技术、跨学科方法解决社会治理、文化传承、公共服务等真实问题，赛道含数字人文、社会治理、文化创意与国际传播。评审看重三点：问题是否真实、方法是否跨学科、成果能否被实际使用。文科生参加这类赛事，最忌讳只交一份漂亮的调研报告而没有可验证的产出。",
    "sdnu-013": "由中国包装联合会主办的行业赛事，聚焦包装结构设计、视觉设计与可持续材料应用，评审团含包装企业与品牌方设计师。比赛通常要求提交完整的包装方案：结构展开图、材料选择理由、印刷工艺说明与货架陈列效果。因为直接对接产业，获奖作品有较大概率被企业看中并落地，是设计类赛事中产业化程度较高的一档。",
}
